import * as THREE from '../vendor/three.module.js'

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const chance = (p) => Math.random() < p

export function damp(current, target, lambda, dt) {
  return lerp(current, target, 1 - Math.exp(-lambda * dt))
}

export function shortestAngle(a, b) {
  let d = (b - a) % (Math.PI * 2)
  if (d > Math.PI) d -= Math.PI * 2
  if (d < -Math.PI) d += Math.PI * 2
  return d
}

export function dampAngle(current, target, lambda, dt) {
  return current + shortestAngle(current, target) * (1 - Math.exp(-lambda * dt))
}

// Ray / axis-aligned box intersection. Returns { t, normal } or null.
export function rayAABB(origin, dir, box) {
  let tmin = -Infinity
  let tmax = Infinity
  let nAxis = 0
  let nSign = 1
  const o = [origin.x, origin.y, origin.z]
  const d = [dir.x, dir.y, dir.z]
  const mins = [box.minX, box.minY, box.minZ]
  const maxs = [box.maxX, box.maxY, box.maxZ]
  for (let i = 0; i < 3; i++) {
    if (Math.abs(d[i]) < 1e-8) {
      if (o[i] < mins[i] || o[i] > maxs[i]) return null
      continue
    }
    const inv = 1 / d[i]
    let t1 = (mins[i] - o[i]) * inv
    let t2 = (maxs[i] - o[i]) * inv
    let sign = -1
    if (t1 > t2) {
      const tmp = t1
      t1 = t2
      t2 = tmp
      sign = 1
    }
    if (t1 > tmin) {
      tmin = t1
      nAxis = i
      nSign = sign
    }
    tmax = Math.min(tmax, t2)
    if (tmin > tmax) return null
  }
  if (tmax < 0) return null
  const t = tmin >= 0 ? tmin : tmax
  const normal = new THREE.Vector3()
  if (nAxis === 0) normal.x = nSign
  else if (nAxis === 1) normal.y = nSign
  else normal.z = nSign
  return { t, normal }
}

export function raySphere(origin, dir, center, radius) {
  const ox = origin.x - center.x
  const oy = origin.y - center.y
  const oz = origin.z - center.z
  const b = ox * dir.x + oy * dir.y + oz * dir.z
  const c = ox * ox + oy * oy + oz * oz - radius * radius
  const h = b * b - c
  if (h < 0) return null
  const t = -b - Math.sqrt(h)
  return t >= 0 ? t : null
}

export function segmentBlocked(a, b, colliders) {
  const dir = new THREE.Vector3().subVectors(b, a)
  const dist = dir.length()
  if (dist < 0.001) return false
  dir.divideScalar(dist)
  const minY = Math.min(a.y, b.y)
  const maxY = Math.max(a.y, b.y)
  for (const c of colliders) {
    if (c.maxY < minY + 0.02 || c.minY > maxY - 0.02) continue
    const hit = rayAABB(a, dir, c)
    if (hit && hit.t > 0.05 && hit.t < dist - 0.12) return true
  }
  return false
}

export function pointInExpandedBox(x, z, c, r) {
  return x > c.minX - r && x < c.maxX + r && z > c.minZ - r && z < c.maxZ + r
}

export function resolveCircle(x, z, r, colliders, feetY = 0, headY = 1.8) {
  let px = x
  let pz = z
  for (let pass = 0; pass < 2; pass++) {
    for (const c of colliders) {
      if (c.maxY < feetY + 0.08 || c.minY > headY) continue
      const cx = clamp(px, c.minX, c.maxX)
      const cz = clamp(pz, c.minZ, c.maxZ)
      let dx = px - cx
      let dz = pz - cz
      const d2 = dx * dx + dz * dz
      if (d2 >= r * r) continue
      if (d2 > 1e-8) {
        const d = Math.sqrt(d2)
        const push = r - d + 0.001
        px += (dx / d) * push
        pz += (dz / d) * push
      } else {
        const left = px - c.minX
        const right = c.maxX - px
        const near = pz - c.minZ
        const far = c.maxZ - pz
        const m = Math.min(left, right, near, far)
        if (m === left) px = c.minX - r
        else if (m === right) px = c.maxX + r
        else if (m === near) pz = c.minZ - r
        else pz = c.maxZ + r
      }
    }
  }
  return { x: px, z: pz }
}

export function collidesCircle(x, z, r, colliders, feetY = 0, headY = 1.8) {
  for (const c of colliders) {
    if (c.maxY < feetY + 0.08 || c.minY > headY) continue
    const cx = clamp(x, c.minX, c.maxX)
    const cz = clamp(z, c.minZ, c.maxZ)
    const dx = x - cx
    const dz = z - cz
    if (dx * dx + dz * dz < r * r) return true
  }
  return false
}

export function makeCanvas(w, h) {
  const c = document.createElement('canvas')
  c.width = w
  c.height = h
  return c
}

export function canvasTexture(canvas, repeatX = 1, repeatY = 1) {
  const tex = new THREE.CanvasTexture(canvas)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = THREE.RepeatWrapping
  tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(repeatX, repeatY)
  tex.anisotropy = 4
  return tex
}

export function easeOutCubic(t) {
  return 1 - Math.pow(1 - t, 3)
}

export function formatTime(seconds) {
  const m = Math.floor(seconds / 60)
  const s = Math.floor(seconds % 60)
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
}

export function disposeObject(obj) {
  obj.traverse((o) => {
    if (o.geometry) o.geometry.dispose?.()
    if (o.material) {
      if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.())
      else o.material.dispose?.()
    }
  })
}

import * as THREE from '../vendor/three.module.js'
import { makeCanvas, canvasTexture, rand, randInt } from './utils.js'

function noiseOverlay(ctx, w, h, count, alpha, light = true) {
  for (let i = 0; i < count; i++) {
    const g = rand(0, 255)
    ctx.fillStyle = `rgba(${g},${g},${g},${rand(alpha * 0.2, alpha)})`
    const s = rand(0.5, 2.5)
    ctx.fillRect(rand(0, w), rand(0, h), s, s)
  }
}

function stains(ctx, w, h, count, color) {
  for (let i = 0; i < count; i++) {
    const x = rand(0, w)
    const y = rand(0, h)
    const r = rand(w * 0.02, w * 0.16)
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, color)
    g.addColorStop(0.45, color.replace(/[\d.]+\)$/, '0.05)'))
    g.addColorStop(1, color.replace(/[\d.]+\)$/, '0)'))
    ctx.fillStyle = g
    ctx.fillRect(x - r, y - r, r * 2, r * 2)
  }
}

export function makeConcreteFloor() {
  const w = 512
  const h = 512
  const c = makeCanvas(w, h)
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#3b3d3b'
  ctx.fillRect(0, 0, w, h)
  // Broad tonal patches
  for (let i = 0; i < 50; i++) {
    const x = rand(0, w)
    const y = rand(0, h)
    const r = rand(20, 100)
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    const tone = randInt(45, 78)
    g.addColorStop(0, `rgba(${tone},${tone + 2},${tone - 1},${rand(0.04, 0.16)})`)
    g.addColorStop(1, 'rgba(50,52,50,0)')
    ctx.fillStyle = g
    ctx.fillRect(x - r, y - r, r * 2, r * 2)
  }
  noiseOverlay(ctx, w, h, 16000, 0.12)
  stains(ctx, w, h, 16, 'rgba(12,13,12,0.3)')
  stains(ctx, w, h, 7, 'rgba(70,52,32,0.22)')
  // Slab seams
  ctx.strokeStyle = 'rgba(15,16,15,0.7)'
  ctx.lineWidth = 2
  ctx.beginPath()
  ctx.moveTo(0, 256)
  ctx.lineTo(w, 256)
  ctx.moveTo(256, 0)
  ctx.lineTo(256, h)
  ctx.stroke()
  ctx.strokeStyle = 'rgba(115,118,112,0.12)'
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(0, 259)
  ctx.lineTo(w, 259)
  ctx.moveTo(259, 0)
  ctx.lineTo(259, h)
  ctx.stroke()
  // Cracks
  for (let i = 0; i < 13; i++) {
    let x = rand(0, w)
    let y = rand(0, h)
    ctx.strokeStyle = `rgba(15,16,15,${rand(0.25, 0.65)})`
    ctx.lineWidth = rand(0.5, 1.5)
    ctx.beginPath()
    ctx.moveTo(x, y)
    const steps = randInt(4, 12)
    for (let j = 0; j < steps; j++) {
      x += rand(-18, 18)
      y += rand(-18, 18)
      ctx.lineTo(x, y)
    }
    ctx.stroke()
  }
  // Faint painted lane line
  ctx.fillStyle = 'rgba(178,150,42,0.13)'
  ctx.fillRect(0, 64, w, 9)
  ctx.fillRect(0, 430, w, 9)
  noiseOverlay(ctx, w, h, 3000, 0.08)
  return canvasTexture(c, 9, 11)
}

export function makeConcreteFloorRough() {
  const w = 256
  const c = makeCanvas(w, w)
  const ctx = c.getContext('2d')
  const img = ctx.createImageData(w, w)
  for (let i = 0; i < w * w; i++) {
    const v = randInt(140, 240)
    img.data[i * 4] = v
    img.data[i * 4 + 1] = v
    img.data[i * 4 + 2] = v
    img.data[i * 4 + 3] = 255
  }
  ctx.putImageData(img, 0, 0)
  return canvasTexture(c, 9, 11)
}

export function makeConcreteWall() {
  const w = 512
  const h = 512
  const c = makeCanvas(w, h)
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#414541'
  ctx.fillRect(0, 0, w, h)
  for (let i = 0; i < 30; i++) {
    const x = rand(0, w)
    const y = rand(0, h)
    const r = rand(30, 130)
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    const tone = randInt(42, 84)
    g.addColorStop(0, `rgba(${tone},${tone + 3},${tone},${rand(0.05, 0.2)})`)
    g.addColorStop(1, 'rgba(50,52,50,0)')
    ctx.fillStyle = g
    ctx.fillRect(x - r, y - r, r * 2, r * 2)
  }
  noiseOverlay(ctx, w, h, 12000, 0.14)
  stains(ctx, w, h, 22, 'rgba(14,15,13,0.35)')
  // Formwork panel seams
  ctx.strokeStyle = 'rgba(20,21,19,0.65)'
  ctx.lineWidth = 2
  for (let y = 0; y < h; y += 170) {
    ctx.beginPath()
    ctx.moveTo(0, y)
    ctx.lineTo(w, y)
    ctx.stroke()
    ctx.strokeStyle = 'rgba(120,122,115,0.1)'
    ctx.beginPath()
    ctx.moveTo(0, y + 3)
    ctx.lineTo(w, y + 3)
    ctx.stroke()
    ctx.strokeStyle = 'rgba(20,21,19,0.65)'
  }
  // Grime streaks
  for (let i = 0; i < 28; i++) {
    const x = rand(0, w)
    const y = rand(0, h * 0.55)
    const len = rand(30, 220)
    const g = ctx.createLinearGradient(x, y, x, y + len)
    g.addColorStop(0, 'rgba(12,14,12,0.25)')
    g.addColorStop(1, 'rgba(12,14,12,0)')
    ctx.fillStyle = g
    ctx.fillRect(x, y, rand(2, 9), len)
  }
  return canvasTexture(c, 4, 2)
}

export function makeContainer(color = '#5e3328', label = 'TRANSCORP') {
  const w = 1024
  const h = 512
  const c = makeCanvas(w, h)
  const ctx = c.getContext('2d')
  ctx.fillStyle = color
  ctx.fillRect(0, 0, w, h)
  // Corrugation
  for (let x = 0; x < w; x += 26) {
    const g = ctx.createLinearGradient(x, 0, x + 26, 0)
    g.addColorStop(0, 'rgba(0,0,0,0.24)')
    g.addColorStop(0.28, 'rgba(255,255,255,0.07)')
    g.addColorStop(0.55, 'rgba(255,255,255,0.13)')
    g.addColorStop(0.8, 'rgba(0,0,0,0.2)')
    g.addColorStop(1, 'rgba(0,0,0,0.32)')
    ctx.fillStyle = g
    ctx.fillRect(x, 0, 26, h)
  }
  // Top/bottom rails
  ctx.fillStyle = 'rgba(0,0,0,0.38)'
  ctx.fillRect(0, 0, w, 34)
  ctx.fillRect(0, h - 38, w, 38)
  ctx.fillStyle = 'rgba(255,255,255,0.06)'
  ctx.fillRect(0, 34, w, 5)
  // Rust patches
  for (let i = 0; i < 38; i++) {
    const x = rand(0, w)
    const y = rand(0, h)
    const r = rand(4, 42)
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, `rgba(${randInt(74, 105)},${randInt(42, 62)},${randInt(22, 38)},${rand(0.18, 0.58)})`)
    g.addColorStop(1, 'rgba(90,45,20,0)')
    ctx.fillStyle = g
    ctx.fillRect(x - r, y - r, r * 2, r * 2)
  }
  noiseOverlay(ctx, w, h, 9000, 0.1)
  // Stenciled branding
  ctx.save()
  ctx.globalAlpha = 0.72
  ctx.fillStyle = '#d8d3c2'
  ctx.font = 'bold 68px "Arial Narrow", Arial, sans-serif'
  ctx.letterSpacing = '6px'
  ctx.fillText(label, 54, 148)
  ctx.font = 'bold 26px "Courier New", monospace'
  ctx.fillStyle = '#c8c2b2'
  ctx.fillText('DRY FREIGHT  //  40FT  //  MAX 30,480 KG', 58, 190)
  ctx.font = 'bold 96px "Courier New", monospace'
  ctx.fillStyle = 'rgba(20,20,18,0.45)'
  ctx.fillText('BLK-' + randInt(1000, 9999), 660, 420)
  ctx.restore()
  // Door bars on right end
  ctx.fillStyle = 'rgba(20,20,20,0.45)'
  ctx.fillRect(w - 82, 34, 82, h - 72)
  for (let i = 0; i < 5; i++) {
    ctx.fillStyle = 'rgba(200,200,190,0.14)'
    ctx.fillRect(w - 70, 60 + i * 76, 58, 8)
  }
  return canvasTexture(c, 1, 1)
}

export function makeWoodCrate() {
  const s = 512
  const c = makeCanvas(s, s)
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#59452e'
  ctx.fillRect(0, 0, s, s)
  for (let y = 0; y < s; y += 64) {
    ctx.fillStyle = `rgba(${randInt(80, 110)},${randInt(60, 82)},${randInt(38, 55)},0.55)`
    ctx.fillRect(0, y, s, 62)
    ctx.fillStyle = 'rgba(25,18,10,0.55)'
    ctx.fillRect(0, y + 62, s, 3)
    // grain
    for (let i = 0; i < 20; i++) {
      ctx.strokeStyle = `rgba(30,20,10,${rand(0.08, 0.22)})`
      ctx.lineWidth = rand(0.5, 1.6)
      const yy = y + rand(5, 55)
      ctx.beginPath()
      ctx.moveTo(0, yy)
      for (let x = 0; x < s; x += 40) ctx.lineTo(x, yy + rand(-2, 2))
      ctx.stroke()
    }
  }
  // Frame
  ctx.strokeStyle = 'rgba(48,34,20,0.9)'
  ctx.lineWidth = 26
  ctx.strokeRect(13, 13, s - 26, s - 26)
  ctx.strokeStyle = 'rgba(135,104,65,0.18)'
  ctx.lineWidth = 4
  ctx.strokeRect(28, 28, s - 56, s - 56)
  ctx.save()
  ctx.rotate(-0.045)
  ctx.fillStyle = 'rgba(210,205,188,0.48)'
  ctx.font = 'bold 34px "Courier New", monospace'
  ctx.fillText('MIL-SURPLUS', 124, 240)
  ctx.font = 'bold 21px "Courier New", monospace'
  ctx.fillText('LOT 88-B / FRAGILE', 146, 274)
  ctx.restore()
  stains(ctx, s, s, 10, 'rgba(20,13,7,0.3)')
  return canvasTexture(c, 1, 1)
}

export function makeHazard() {
  const w = 512
  const h = 128
  const c = makeCanvas(w, h)
  const ctx = c.getContext('2d')
  ctx.fillStyle = '#b69b2c'
  ctx.fillRect(0, 0, w, h)
  ctx.fillStyle = '#171817'
  for (let x = -h; x < w + h; x += 64) {
    ctx.beginPath()
    ctx.moveTo(x, h)
    ctx.lineTo(x + 32, h)
    ctx.lineTo(x + 32 + h, 0)
    ctx.lineTo(x + h, 0)
    ctx.closePath()
    ctx.fill()
  }
  // wear
  for (let i = 0; i < 120; i++) {
    ctx.fillStyle = `rgba(50,48,40,${rand(0.1, 0.4)})`
    ctx.fillRect(rand(0, w), rand(0, h), rand(1, 10), rand(1, 4))
  }
  return canvasTexture(c, 3, 1)
}

