    polymer: new THREE.MeshStandardMaterial({ color: 0x2d3029, roughness: 0.8, metalness: 0.08 }),
    fde: new THREE.MeshStandardMaterial({ color: 0x6b6046, roughness: 0.72, metalness: 0.12 }),
    steel: new THREE.MeshStandardMaterial({ color: 0x5e6464, roughness: 0.28, metalness: 0.9 }),
    glove: new THREE.MeshStandardMaterial({ color: 0x242522, roughness: 0.92, metalness: 0.02 }),
