import * as THREE from '../vendor/three.module.js'

export function createPost(renderer) {
  const size = renderer.getDrawingBufferSize(new THREE.Vector2())
  const target = new THREE.WebGLRenderTarget(size.x, size.y, {
    type: THREE.HalfFloatType,
    minFilter: THREE.LinearFilter,
    magFilter: THREE.LinearFilter,
    depthBuffer: true,
    stencilBuffer: false,
  })
  target.texture.colorSpace = THREE.LinearSRGBColorSpace

  const material = new THREE.ShaderMaterial({
    uniforms: {
      tDiffuse: { value: target.texture },
      uResolution: { value: new THREE.Vector2(size.x, size.y) },
      uTime: { value: 0 },
      uDamage: { value: 0 },
      uLowHealth: { value: 0 },
      uFade: { value: 1 },
      uDistortion: { value: 1 },
    },
    vertexShader: /* glsl */`
      varying vec2 vUv;
      void main() {
        vUv = uv;
        gl_Position = vec4(position.xy, 0.0, 1.0);
      }
    `,
    fragmentShader: /* glsl */`
      precision highp float;
      varying vec2 vUv;
      uniform sampler2D tDiffuse;
      uniform vec2 uResolution;
      uniform float uTime;
      uniform float uDamage;
      uniform float uLowHealth;
      uniform float uFade;
      uniform float uDistortion;

      float hash(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
      }

      vec3 aces(vec3 x) {
        return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
      }

      void main() {
        vec2 p = vUv - 0.5;
        p.x *= 1.0;
        float r2 = dot(p, p);
        float edge = smoothstep(0.18, 0.68, length(p));

        // subtle barrel / fisheye distortion
        vec2 uv = 0.5 + p * (1.0 + (0.085 * r2 + 0.035 * r2 * r2) * uDistortion);

        // chromatic aberration
        vec2 ca = p * (0.0009 + r2 * 0.0027);
        float rr = texture2D(tDiffuse, uv + ca).r;
        float gg = texture2D(tDiffuse, uv).g;
        float bb = texture2D(tDiffuse, uv - ca).b;
        vec3 col = vec3(rr, gg, bb);

        // cheap 8 tap bloom for hot lights and muzzle flashes
        vec2 px = 1.0 / uResolution;
        vec3 bl = vec3(0.0);
        bl += texture2D(tDiffuse, uv + px * vec2(5.0, 0.0)).rgb;
        bl += texture2D(tDiffuse, uv + px * vec2(-5.0, 0.0)).rgb;
        bl += texture2D(tDiffuse, uv + px * vec2(0.0, 5.0)).rgb;
        bl += texture2D(tDiffuse, uv + px * vec2(0.0, -5.0)).rgb;
        bl += texture2D(tDiffuse, uv + px * vec2(10.0, 8.0)).rgb;
        bl += texture2D(tDiffuse, uv + px * vec2(-10.0, -8.0)).rgb;
        bl += texture2D(tDiffuse, uv + px * vec2(9.0, -9.0)).rgb;
        bl += texture2D(tDiffuse, uv + px * vec2(-9.0, 9.0)).rgb;
        bl *= 0.125;
        float blLum = max(max(bl.r, bl.g), bl.b);
        col += bl * smoothstep(0.58, 1.4, blLum) * 0.42;

        // grade: cool shadows, warm practicals
        float luma = dot(col, vec3(0.299, 0.587, 0.114));
        col = mix(vec3(luma), col, 1.16);
        col *= vec3(1.04, 1.0, 0.95);
        col += vec3(0.004, 0.009, 0.014) * (1.0 - smoothstep(0.0, 0.45, luma));
        col = pow(max(col, 0.0), vec3(0.92, 1.0, 1.07));

        // bodycam lens vignette
        float vig = smoothstep(0.86, 0.19, length(p * vec2(1.02, 1.0)));
        col *= mix(0.42, 1.0, vig);

        // scanlines / sensor lines
        col *= 1.0 - 0.016 * (0.5 + 0.5 * sin(vUv.y * uResolution.y * 1.6));
        // faint horizontal sensor band
        float band = smoothstep(0.02, 0.0, abs(fract(vUv.y * 0.5 + uTime * 0.015) - 0.5));
        col += vec3(0.008, 0.011, 0.014) * band;

        // lens smudges
        float smudge = 0.0;
        smudge += smoothstep(0.17, 0.0, length(vUv - vec2(0.23, 0.72))) * 0.18;
        smudge += smoothstep(0.22, 0.0, length(vUv - vec2(0.79, 0.32))) * 0.13;
        smudge += smoothstep(0.11, 0.0, length(vUv - vec2(0.63, 0.79))) * 0.1;
        col *= 1.0 - smudge;

        // film grain, stronger in shadows
        float grain = hash(vUv * uResolution + fract(uTime) * 431.0) - 0.5;
        col += grain * (0.045 + 0.02 * (1.0 - luma));
        // fixed pattern noise
        col += (hash(floor(vUv * uResolution * 0.5) + 5.0) - 0.5) * 0.012;

        // damage wash + low health pulse
        float hurt = uDamage * smoothstep(0.15, 0.78, length(p));
        col = mix(col, vec3(0.45, 0.015, 0.008), hurt * 0.78);
        float pulse = 0.5 + 0.5 * sin(uTime * 5.2);
        float low = uLowHealth * smoothstep(0.28, 0.8, length(p)) * (0.3 + 0.22 * pulse);
        col = mix(col, vec3(0.34, 0.01, 0.006), low * 0.55);

        // slight exposure breathing and camera sensor flicker
        col *= 0.985 + 0.015 * sin(uTime * 8.0);
        col = aces(col * 1.08);
        col = pow(max(col, 0.0), vec3(1.0 / 2.2));

        gl_FragColor = vec4(col * uFade, 1.0);
      }
    `,
    depthTest: false,
    depthWrite: false,
  })

  const postScene = new THREE.Scene()
  const postCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1)
  const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material)
  quad.frustumCulled = false
  postScene.add(quad)

  const setSize = (w, h) => {
    target.setSize(w, h)
    material.uniforms.uResolution.value.set(w, h)
  }

  return {
    target,
    material,
    postScene,
    postCamera,
    setSize,
    render(renderer, scene, camera, weaponScene, weaponCamera) {
      renderer.setRenderTarget(target)
      renderer.clear()
      renderer.render(scene, camera)
      if (weaponScene) {
        renderer.clearDepth()
        renderer.render(weaponScene, weaponCamera)
      }
      renderer.setRenderTarget(null)
      renderer.render(postScene, postCamera)
    },
  }
}

import { clamp, rand } from './utils.js'

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.ambientGain = null
    this.muted = false
    this.noiseBuffer = null
    this.started = false
    this.nextAmbient = rand(7, 16)
  }

  init() {
    if (this.ctx) {
      this.ctx.resume?.()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.46
    this.master.connect(this.ctx.destination)
    this.noiseBuffer = this.makeNoise(2.0)
    this.startAmbient()
    this.started = true
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds)
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    return buffer
  }

  startAmbient() {
    const ctx = this.ctx
    // low industrial drone
    const drone = ctx.createGain()
    drone.gain.value = 0.022
    drone.connect(this.master)
    for (const [freq, gain] of [[43, 1], [57, 0.5], [86, 0.24]]) {
      const osc = ctx.createOscillator()
      osc.type = 'sawtooth'
      osc.frequency.value = freq
      const f = ctx.createBiquadFilter()
      f.type = 'lowpass'
      f.frequency.value = 180
      const g = ctx.createGain()
      g.gain.value = gain
      osc.connect(f).connect(g).connect(drone)
      osc.start()
    }
    // air handling / rain hiss
    const noise = ctx.createBufferSource()
    noise.buffer = this.noiseBuffer
    noise.loop = true
    const bp = ctx.createBiquadFilter()
    bp.type = 'bandpass'
    bp.frequency.value = 620
    bp.Q.value = 0.5
    const g = ctx.createGain()
    g.gain.value = 0.018
    noise.connect(bp).connect(g).connect(this.master)
    noise.start()
    // fluorescent buzz
    const buzz = ctx.createOscillator()
    buzz.type = 'sine'
    buzz.frequency.value = 120
    const buzzGain = ctx.createGain()
    buzzGain.gain.value = 0.004
    buzz.connect(buzzGain).connect(this.master)
    buzz.start()
    this.ambientGain = drone
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.46, this.ctx.currentTime, 0.05)
  }

  shot(kind = 'rifle') {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const isRifle = kind === 'rifle'
    // crack noise
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = rand(0.9, 1.15)
    const hp = ctx.createBiquadFilter()
    hp.type = 'highpass'
    hp.frequency.value = isRifle ? 280 : 480
    const lp = ctx.createBiquadFilter()
    lp.type = 'lowpass'
    lp.frequency.setValueAtTime(isRifle ? 7200 : 9000, now)
    lp.frequency.exponentialRampToValueAtTime(700, now + 0.12)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, now)
    g.gain.exponentialRampToValueAtTime(isRifle ? 0.7 : 0.55, now + 0.004)
    g.gain.exponentialRampToValueAtTime(0.0001, now + (isRifle ? 0.16 : 0.12))
    src.connect(hp).connect(lp).connect(g).connect(this.master)
    src.start(now)
    src.stop(now + 0.2)
    // low body thump
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(isRifle ? 105 : 150, now)
    osc.frequency.exponentialRampToValueAtTime(38, now + 0.14)
    const og = ctx.createGain()
    og.gain.setValueAtTime(0.0001, now)
    og.gain.exponentialRampToValueAtTime(0.55, now + 0.005)
    og.gain.exponentialRampToValueAtTime(0.0001, now + 0.18)
    osc.connect(og).connect(this.master)
    osc.start(now)
    osc.stop(now + 0.2)
    // mechanical click
    this.click(0.03, 0.14)
  }

  enemyShot(position, distance) {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const vol = clamp(1 - distance / 55, 0.05, 1)
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = rand(0.8, 1.0)
    const lp = ctx.createBiquadFilter()
    lp.type = 'lowpass'
    lp.frequency.value = 900 + (1 - vol) * 500
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, now)
    g.gain.exponentialRampToValueAtTime(0.38 * vol * vol, now + 0.006)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.2 + distance * 0.003)
    src.connect(lp).connect(g).connect(this.master)
    src.start(now)
    src.stop(now + 0.3 + distance * 0.003)
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(80, now)
    osc.frequency.exponentialRampToValueAtTime(35, now + 0.2)
    const og = ctx.createGain()
    og.gain.setValueAtTime(0.3 * vol, now)
    og.gain.exponentialRampToValueAtTime(0.0001, now + 0.25)
    osc.connect(og).connect(this.master)
    osc.start(now)
    osc.stop(now + 0.28)
  }

  click(volume = 0.2, freq = 1200, when = 0) {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime + when
    const osc = ctx.createOscillator()
    osc.type = 'square'
    osc.frequency.setValueAtTime(freq, now)
    osc.frequency.exponentialRampToValueAtTime(freq * 0.45, now + 0.03)
    const g = ctx.createGain()
    g.gain.setValueAtTime(volume, now)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.045)
    osc.connect(g).connect(this.master)
    osc.start(now)
    osc.stop(now + 0.06)
  }

  reload() {
    if (!this.ctx) return
    this.click(0.14, 900, 0.02)
    this.click(0.12, 650, 0.24)
    this.click(0.18, 1100, 1.0)
    this.click(0.15, 750, 1.45)
  }

  empty() {
    this.click(0.16, 1500)
    this.click(0.1, 900, 0.03)
  }

  footstep(sprint = false) {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = rand(0.55, 0.8)
    const lp = ctx.createBiquadFilter()
    lp.type = 'lowpass'
    lp.frequency.value = rand(220, 340)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, now)
    g.gain.exponentialRampToValueAtTime(sprint ? 0.14 : 0.08, now + 0.008)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.1)
    src.connect(lp).connect(g).connect(this.master)
    src.start(now)
    src.stop(now + 0.12)
    // gear rattle
    if (Math.random() < 0.35) this.click(0.018, rand(2200, 3600), 0.015)
  }

  hitmarker(head = false) {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(head ? 1750 : 1250, now)
    osc.frequency.exponentialRampToValueAtTime(head ? 2100 : 1550, now + 0.035)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.12, now)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.07)
    osc.connect(g).connect(this.master)
    osc.start(now)
    osc.stop(now + 0.08)
  }

  hurt() {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(95, now)
    osc.frequency.exponentialRampToValueAtTime(32, now + 0.32)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.55, now)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.42)
    osc.connect(g).connect(this.master)
    osc.start(now)
    osc.stop(now + 0.45)
    const ring = ctx.createOscillator()
    ring.type = 'sine'
    ring.frequency.value = 3400
    const rg = ctx.createGain()
    rg.gain.setValueAtTime(0.018, now)
    rg.gain.exponentialRampToValueAtTime(0.0001, now + 0.55)
    ring.connect(rg).connect(this.master)
    ring.start(now)
    ring.stop(now + 0.6)
  }

  nearMiss() {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = 1.8
    const bp = ctx.createBiquadFilter()
    bp.type = 'bandpass'
    bp.frequency.setValueAtTime(2200, now)
    bp.frequency.exponentialRampToValueAtTime(500, now + 0.1)
    bp.Q.value = 1.5
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.11, now)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.12)
    src.connect(bp).connect(g).connect(this.master)
    src.start(now)
    src.stop(now + 0.14)
  }

  pickup() {
    if (!this.ctx) return
    this.click(0.1, 900, 0)
    this.click(0.12, 1350, 0.09)
    this.click(0.12, 1800, 0.18)
  }

  radio() {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = 1.2
    const hp = ctx.createBiquadFilter()
    hp.type = 'highpass'
    hp.frequency.value = 1200
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, now)
    g.gain.exponentialRampToValueAtTime(0.08, now + 0.01)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.16)
    src.connect(hp).connect(g).connect(this.master)
    src.start(now)
    src.stop(now + 0.18)
    this.click(0.06, 1900, 0.18)
  }

  win() {
    if (!this.ctx) return
    const notes = [440, 554, 659, 880]
    notes.forEach((f, i) => {
      const ctx = this.ctx
      const now = ctx.currentTime + i * 0.14
      const osc = ctx.createOscillator()
      osc.type = 'sine'
      osc.frequency.value = f
      const g = ctx.createGain()
      g.gain.setValueAtTime(0.0001, now)
      g.gain.exponentialRampToValueAtTime(0.16, now + 0.02)
      g.gain.exponentialRampToValueAtTime(0.0001, now + 0.5)
      osc.connect(g).connect(this.master)
      osc.start(now)
      osc.stop(now + 0.55)
    })
  }

  lose() {
    if (!this.ctx) return
    const ctx = this.ctx
    const now = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(120, now)
    osc.frequency.exponentialRampToValueAtTime(38, now + 1.2)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.3, now)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 1.5)
    osc.connect(g).connect(this.master)
    osc.start(now)
    osc.stop(now + 1.6)
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = 0.35
    const lp = ctx.createBiquadFilter()
    lp.type = 'lowpass'
    lp.frequency.value = 500
    const ng = ctx.createGain()
    ng.gain.setValueAtTime(0.12, now)
    ng.gain.exponentialRampToValueAtTime(0.0001, now + 1.2)
    src.connect(lp).connect(ng).connect(this.master)
    src.start(now)
    src.stop(now + 1.3)
  }

  update(dt) {
    if (!this.ctx || !this.started) return
    this.nextAmbient -= dt
    if (this.nextAmbient <= 0) {
      this.nextAmbient = rand(9, 24)
      this.distantClank()
    }
  }

  distantClank() {
    const ctx = this.ctx
    const now = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = 'triangle'
    osc.frequency.setValueAtTime(rand(180, 380), now)
    osc.frequency.exponentialRampToValueAtTime(rand(60, 120), now + 0.6)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, now)
    g.gain.exponentialRampToValueAtTime(rand(0.02, 0.055), now + 0.01)
    g.gain.exponentialRampToValueAtTime(0.0001, now + 1.3)
    osc.connect(g).connect(this.master)
    osc.start(now)
    osc.stop(now + 1.4)
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.playbackRate.value = 0.6
    const bp = ctx.createBiquadFilter()
    bp.type = 'bandpass'
    bp.frequency.value = rand(300, 700)
    const ng = ctx.createGain()
    ng.gain.setValueAtTime(0.0001, now)
    ng.gain.exponentialRampToValueAtTime(rand(0.008, 0.02), now + 0.02)
    ng.gain.exponentialRampToValueAtTime(0.0001, now + 0.4)
    src.connect(bp).connect(ng).connect(this.master)
    src.start(now)
    src.stop(now + 0.5)
  }
}

import * as THREE from '../vendor/three.module.js'
import { rand, randInt } from './utils.js'

export class Effects {
  constructor(scene, textures) {
    this.scene = scene
    this.textures = textures
    this.sparkCount = 700
    this.sparkGeo = new THREE.BufferGeometry()
    this.sparkPos = new Float32Array(this.sparkCount * 3)
    this.sparkCol = new Float32Array(this.sparkCount * 3)
    this.sparkVel = new Float32Array(this.sparkCount * 3)
    this.sparkLife = new Float32Array(this.sparkCount)
    this.sparkMax = new Float32Array(this.sparkCount)
    this.sparkGeo.setAttribute('position', new THREE.BufferAttribute(this.sparkPos, 3))
    this.sparkGeo.setAttribute('color', new THREE.BufferAttribute(this.sparkCol, 3))
    for (let i = 0; i < this.sparkCount; i++) this.sparkPos[i * 3 + 1] = -100
    this.sparkMat = new THREE.PointsMaterial({
      size: 0.035, vertexColors: true, transparent: true, opacity: 0.95,
      depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true,
    })
    this.sparks = new THREE.Points(this.sparkGeo, this.sparkMat)
    this.sparks.frustumCulled = false
    scene.add(this.sparks)
    this.sparkIndex = 0

    // Blood droplets (non additive)
    this.bloodCount = 320
    this.bloodGeo = new THREE.BufferGeometry()
    this.bloodPos = new Float32Array(this.bloodCount * 3)
    this.bloodCol = new Float32Array(this.bloodCount * 3)
    this.bloodVel = new Float32Array(this.bloodCount * 3)
    this.bloodLife = new Float32Array(this.bloodCount)
    this.bloodMax = new Float32Array(this.bloodCount)
    this.bloodGeo.setAttribute('position', new THREE.BufferAttribute(this.bloodPos, 3))
    this.bloodGeo.setAttribute('color', new THREE.BufferAttribute(this.bloodCol, 3))
    for (let i = 0; i < this.bloodCount; i++) this.bloodPos[i * 3 + 1] = -100
    this.bloodMat = new THREE.PointsMaterial({
      size: 0.055, vertexColors: true, transparent: true, opacity: 0.9,
      depthWrite: false, sizeAttenuation: true,
    })
    this.blood = new THREE.Points(this.bloodGeo, this.bloodMat)
    this.blood.frustumCulled = false
    scene.add(this.blood)
    this.bloodIndex = 0

    // Tracers
    this.tracers = []
    for (let i = 0; i < 22; i++) {
      const geo = new THREE.BufferGeometry()
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3))
      const mat = new THREE.LineBasicMaterial({
        color: 0xffd08a, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false,
      })
      const line = new THREE.Line(geo, mat)
      line.frustumCulled = false
      line.visible = false
      scene.add(line)
      this.tracers.push({ line, life: 0, max: 0.09 })
    }
    this.tracerIndex = 0

    // Smoke puffs
    this.smoke = []
    for (let i = 0; i < 28; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({
        map: textures.smoke, color: 0x6d7475, transparent: true, opacity: 0,
        depthWrite: false, blending: THREE.NormalBlending,
      }))
      s.visible = false
      scene.add(s)
      this.smoke.push({ sprite: s, life: 0, max: 1, vel: new THREE.Vector3(), grow: 1 })
    }
    this.smokeIndex = 0

    // muzzle light
    this.flashLight = new THREE.PointLight(0xffb15a, 0, 10, 2)
    this.flashLight.position.set(0, 1.5, 0)
    scene.add(this.flashLight)
    this.flashTime = 0
  }

  spawnSparks(point, normal, count = 10, color = new THREE.Color(0xffc36a), speed = 2.6) {
    for (let i = 0; i < count; i++) {
      const idx = this.sparkIndex++ % this.sparkCount
      this.sparkPos[idx * 3] = point.x
      this.sparkPos[idx * 3 + 1] = point.y
      this.sparkPos[idx * 3 + 2] = point.z
      const v = new THREE.Vector3(
        normal.x + rand(-1, 1),
        normal.y + rand(-0.2, 1.2),
        normal.z + rand(-1, 1),
      ).normalize().multiplyScalar(rand(0.6, 1) * speed)
      this.sparkVel[idx * 3] = v.x
      this.sparkVel[idx * 3 + 1] = v.y
      this.sparkVel[idx * 3 + 2] = v.z
      this.sparkCol[idx * 3] = color.r
      this.sparkCol[idx * 3 + 1] = color.g
      this.sparkCol[idx * 3 + 2] = color.b
      this.sparkLife[idx] = this.sparkMax[idx] = rand(0.18, 0.55)
    }
    this.sparkGeo.attributes.position.needsUpdate = true
    this.sparkGeo.attributes.color.needsUpdate = true
  }

  spawnBlood(point, dir, count = 10) {
    for (let i = 0; i < count; i++) {
      const idx = this.bloodIndex++ % this.bloodCount
      this.bloodPos[idx * 3] = point.x
      this.bloodPos[idx * 3 + 1] = point.y
      this.bloodPos[idx * 3 + 2] = point.z
      const v = new THREE.Vector3(
        dir.x * rand(0.2, 1.4) + rand(-0.7, 0.7),
        rand(-0.2, 1.0),
        dir.z * rand(0.2, 1.4) + rand(-0.7, 0.7),
      )
      this.bloodVel[idx * 3] = v.x
      this.bloodVel[idx * 3 + 1] = v.y
      this.bloodVel[idx * 3 + 2] = v.z
      const dark = rand(0.25, 0.6)
      this.bloodCol[idx * 3] = 0.35 * dark
      this.bloodCol[idx * 3 + 1] = 0.01
      this.bloodCol[idx * 3 + 2] = 0.015
      this.bloodLife[idx] = this.bloodMax[idx] = rand(0.4, 1.1)
    }
    this.bloodGeo.attributes.position.needsUpdate = true
    this.bloodGeo.attributes.color.needsUpdate = true
  }

  spawnTracer(from, to, color = 0xffc985) {
    const item = this.tracers[this.tracerIndex++ % this.tracers.length]
    const arr = item.line.geometry.attributes.position.array
    arr[0] = from.x; arr[1] = from.y; arr[2] = from.z
    arr[3] = to.x; arr[4] = to.y; arr[5] = to.z
    item.line.geometry.attributes.position.needsUpdate = true
    item.line.material.color.setHex(color)
    item.line.material.opacity = 0.9
    item.line.visible = true
    item.life = item.max
  }

  muzzleFlash(position) {
    this.flashLight.position.copy(position)
    this.flashTime = 0.055
  }

  spawnSmoke(point, size = 0.4, color = 0x7f8585) {
    const item = this.smoke[this.smokeIndex++ % this.smoke.length]
    item.sprite.visible = true
    item.sprite.position.copy(point)
    item.sprite.scale.setScalar(size)
    item.sprite.material.color.setHex(color)
    item.sprite.material.opacity = 0.35
    item.vel.set(rand(-0.15, 0.15), rand(0.15, 0.35), rand(-0.15, 0.15))
    item.life = item.max = rand(0.6, 1.4)
    item.grow = rand(0.7, 1.5)
  }

  update(dt) {
    // sparks
    for (let i = 0; i < this.sparkCount; i++) {
      if (this.sparkLife[i] <= 0) continue
      this.sparkLife[i] -= dt
      if (this.sparkLife[i] <= 0) {
        this.sparkPos[i * 3 + 1] = -100
        continue
      }
      this.sparkVel[i * 3 + 1] -= 5.5 * dt
      this.sparkPos[i * 3] += this.sparkVel[i * 3] * dt
      this.sparkPos[i * 3 + 1] += this.sparkVel[i * 3 + 1] * dt
      this.sparkPos[i * 3 + 2] += this.sparkVel[i * 3 + 2] * dt
      if (this.sparkPos[i * 3 + 1] < 0.02) {
        this.sparkPos[i * 3 + 1] = 0.02
        this.sparkVel[i * 3 + 1] *= -0.28
        this.sparkVel[i * 3] *= 0.6
        this.sparkVel[i * 3 + 2] *= 0.6
      }
      const fade = this.sparkLife[i] / this.sparkMax[i]
      this.sparkCol[i * 3] *= 0.995
      this.sparkCol[i * 3 + 1] *= 0.993
      this.sparkCol[i * 3 + 2] *= 0.99
      if (fade < 0.1) this.sparkPos[i * 3 + 1] = -100
    }
    this.sparkGeo.attributes.position.needsUpdate = true
    this.sparkGeo.attributes.color.needsUpdate = true

    // blood
    for (let i = 0; i < this.bloodCount; i++) {
      if (this.bloodLife[i] <= 0) continue
      this.bloodLife[i] -= dt
      if (this.bloodLife[i] <= 0) {
        this.bloodPos[i * 3 + 1] = -100
        continue
      }
      this.bloodVel[i * 3 + 1] -= 6.0 * dt
      this.bloodPos[i * 3] += this.bloodVel[i * 3] * dt
      this.bloodPos[i * 3 + 1] += this.bloodVel[i * 3 + 1] * dt
      this.bloodPos[i * 3 + 2] += this.bloodVel[i * 3 + 2] * dt
      if (this.bloodPos[i * 3 + 1] < 0.02) {
        this.bloodPos[i * 3 + 1] = 0.02
        this.bloodVel[i * 3 + 1] = 0
        this.bloodVel[i * 3] *= 0.2
        this.bloodVel[i * 3 + 2] *= 0.2
      }
    }
    this.bloodGeo.attributes.position.needsUpdate = true

    // tracers
    for (const item of this.tracers) {
      if (!item.line.visible) continue
      item.life -= dt
      item.line.material.opacity = Math.max(0, item.life / item.max) * 0.9
      if (item.life <= 0) item.line.visible = false
    }

    // smoke
    for (const item of this.smoke) {
      if (!item.sprite.visible) continue
      item.life -= dt
      if (item.life <= 0) {
        item.sprite.visible = false
        continue
      }
      item.sprite.position.addScaledVector(item.vel, dt)
      const p = 1 - item.life / item.max
      item.sprite.scale.setScalar((0.4 + p * item.grow))
      item.sprite.material.opacity = Math.sin(Math.min(1, p * 2.2) * Math.PI) * 0.22
    }

    if (this.flashTime > 0) {
      this.flashTime -= dt
      this.flashLight.intensity = rand(14, 24)
    } else {
      this.flashLight.intensity = 0
    }
  }
}

