@font-face {
  font-family: 'Barlow Condensed';
  src: url('vendor/barlow-condensed-500.ttf') format('truetype');
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('vendor/barlow-condensed-600.ttf') format('truetype');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('vendor/barlow-condensed-700.ttf') format('truetype');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Share Tech Mono';
  src: url('vendor/share-tech-mono.ttf') format('truetype');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #e9e7df;
  --dim: #999a92;
  --dim2: #6f716b;
  --orange: #ff5b21;
  --orange-hot: #ff7b3d;
  --red: #ff3429;
  --green: #76ff9d;
  --cyan: #9ed4ff;
  --panel: rgba(8, 10, 10, 0.82);
  --line: rgba(228, 227, 214, 0.15);
  --cross-gap: 7px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #040506;
  color: var(--ink);
  font-family: 'Barlow Condensed', 'Arial Narrow', Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

body.playing { cursor: none; }
body.menu { cursor: default; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #050607;
}

.hidden { display: none !important; }

/* ==========================================================================
   BODYCAM HUD
   ========================================================================== */
#hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  font-size: 15px;
  letter-spacing: 0.055em;
  text-transform: uppercase;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.85);
}

#hud::before {
  content: '';
  position: absolute;
  inset: 14px;
  border: 1px solid rgba(235, 233, 219, 0.1);
  clip-path: polygon(0 0, 28px 0, 28px 1px, 1px 1px, 1px 28px, 0 28px, 0 0,
    100% 0, 100% 28px, calc(100% - 1px) 28px, calc(100% - 1px) 1px, calc(100% - 28px) 1px, calc(100% - 28px) 0,
    100% 100%, calc(100% - 28px) 100%, calc(100% - 28px) calc(100% - 1px), calc(100% - 1px) calc(100% - 1px),
    calc(100% - 1px) calc(100% - 28px), 100% calc(100% - 28px),
    0 100%, 0 calc(100% - 28px), 1px calc(100% - 28px), 1px calc(100% - 1px), 28px calc(100% - 1px), 28px 100%);
  pointer-events: none;
}

#hud::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.022) 1px, transparent 1px) 0 0 / 25% 100%,
    radial-gradient(ellipse at center, transparent 52%, rgba(0, 0, 0, 0.28) 100%);
  opacity: 0.55;
  pointer-events: none;
}

.hud-frame {
  position: absolute;
  inset: 14px;
  pointer-events: none;
}
.hud-frame::before, .hud-frame::after {
  content: '';
  position: absolute;
  width: 34px;
  height: 34px;
  border-color: rgba(255, 91, 33, 0.45);
  border-style: solid;
}
.hud-frame::before { left: 10px; top: 10px; border-width: 1px 0 0 1px; }
.hud-frame::after { right: 10px; bottom: 10px; border-width: 0 1px 1px 0; }

.hud-top {
  position: absolute;
  top: 27px;
  left: 33px;
  right: 33px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.rec-line { display: flex; align-items: center; gap: 8px; }
.rec-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 10px rgba(255, 52, 41, 0.9);
  animation: blink 1.2s steps(2, end) infinite;
}
@keyframes blink { 0%, 42% { opacity: 1; } 43%, 100% { opacity: 0.15; } }
.rec-label {
  font-weight: 700;
  font-size: 17px;
  letter-spacing: 0.18em;
  color: #fff;
}
.rec-time { font-family: 'Share Tech Mono', monospace; font-size: 13px; color: var(--dim); letter-spacing: 0.03em; }
.rec-sub {
  margin-top: 4px;
  margin-left: 16px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 9.5px;
  color: var(--dim2);
  letter-spacing: 0.12em;
}
.rec-sub span { color: var(--orange); padding: 0 3px; }

.mission-center { text-align: center; min-width: 130px; }
.mission-label { font-size: 9px; letter-spacing: 0.22em; color: var(--dim2); }
.mission-clock {
  font-family: 'Share Tech Mono', monospace;
  font-size: 27px;
  color: var(--ink);
  line-height: 1;
  margin-top: 4px;
  letter-spacing: 0.02em;
}
.mission-center::after {
  content: '';
  display: block;
  width: 100%;
  height: 1px;
  margin-top: 6px;
  background: linear-gradient(90deg, transparent, rgba(255, 91, 33, 0.55), transparent);
}

.system-block { text-align: right; font-family: 'Share Tech Mono', monospace; font-size: 10px; color: var(--dim); }
.system-row { display: flex; justify-content: flex-end; align-items: center; gap: 7px; }
.sig-bars { display: inline-flex; gap: 2px; align-items: flex-end; height: 10px; }
.sig-bars i { display: block; width: 2px; background: var(--green); box-shadow: 0 0 4px rgba(118, 255, 157, 0.5); }
.sig-bars i:nth-child(1) { height: 3px; }
.sig-bars i:nth-child(2) { height: 5px; }
.sig-bars i:nth-child(3) { height: 7px; }
.sig-bars i:nth-child(4) { height: 9px; }
.battery-row { display: flex; justify-content: flex-end; align-items: center; gap: 7px; margin-top: 5px; }
.battery {
  width: 27px;
  height: 11px;
  border: 1px solid rgba(233, 231, 223, 0.55);
  position: relative;
  padding: 1px;
}
.battery::after {
  content: '';
  position: absolute;
  right: -4px;
  top: 3px;
  width: 2px;
  height: 4px;
  background: rgba(233, 231, 223, 0.55);
}
.battery-fill { height: 100%; width: 100%; background: var(--green); transition: width 0.4s; }
.system-sub { margin-top: 5px; color: var(--dim2); font-size: 9px; }
.system-sub span { color: var(--orange); }

.compass-wrap {
  position: absolute;
  top: 91px;
  left: 50%;
  transform: translateX(-50%);
  width: 400px;
  text-align: center;
}
.compass { position: relative; height: 20px; }
.compass-ticks {
  position: absolute;
  inset: 0 0 0 0;
  background: repeating-linear-gradient(90deg, rgba(233, 231, 223, 0.38) 0 1px, transparent 1px 20px);
  mask-image: linear-gradient(90deg, transparent, #000 15%, #000 85%, transparent);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 15%, #000 85%, transparent);
  opacity: 0.7;
}
.compass-ticks::after {
  content: 'W 270       NW       N 000       NE       E 090';
  position: absolute;
  left: 0;
  right: 0;
  top: -13px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  letter-spacing: 0.12em;
  color: rgba(233, 231, 223, 0.4);
  word-spacing: 6px;
  white-space: nowrap;
  overflow: hidden;
}
.compass-needle {
  position: absolute;
