  color: var(--ink);
  margin-top: 1px;
}
.compass-readout .deg { color: var(--dim2); font-size: 9px; }
.compass-readout #cardinal { color: var(--orange); margin-left: 5px; font-size: 12px; }

.obj-marker {
  position: absolute;
  top: 5px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  color: var(--orange);
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  letter-spacing: 0.06em;
  transition: left 0.08s linear;
  white-space: nowrap;
}
.obj-chev { font-size: 9px; line-height: 1; }
.obj-marker.behind { opacity: 0.4; }
.obj-marker.hidden { display: none; }

.obj-panel {
  position: absolute;
  top: 126px;
  left: 33px;
  width: 292px;
  padding-left: 13px;
  border-left: 2px solid rgba(255, 91, 33, 0.7);
}
.panel-label { font-size: 9px; letter-spacing: 0.23em; color: var(--orange); }
.obj-title {
  font-weight: 600;
  font-size: 25px;
  line-height: 1.02;
  margin-top: 4px;
  letter-spacing: 0.035em;
}
.obj-sub { margin-top: 4px; font-family: 'Share Tech Mono', monospace; font-size: 9.5px; color: var(--dim); }
.obj-list { margin-top: 15px; display: flex; flex-direction: column; gap: 5px; }
.obj-item {
  display: grid;
