  border: 1px solid rgba(233, 231, 223, 0.45);
}
.obj-item .count { font-family: 'Share Tech Mono', monospace; font-size: 9px; color: var(--dim2); }
.obj-item.done { color: var(--green); }
.obj-item.done .box { background: var(--green); border-color: var(--green); box-shadow: 0 0 8px rgba(118, 255, 157, 0.55); }
.obj-item.done .count { color: var(--green); }
.obj-item.locked { color: var(--dim2); }
.obj-item.locked .box { border-color: var(--dim2); }

.vitals {
  position: absolute;
  left: 33px;
  bottom: 39px;
