  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(0.55); opacity: 0.35; } }
.vitals-status { margin-left: auto; color: var(--green); font-size: 8px; }
.health-row { display: flex; align-items: center; gap: 12px; margin-top: 7px; }
.health-num {
  font-family: 'Share Tech Mono', monospace;
