}
.stamina-track { flex: 1; height: 2px; background: rgba(233, 231, 223, 0.12); }
.stamina-fill { height: 100%; width: 100%; background: rgba(158, 212, 255, 0.7); transition: width 0.15s; }
.vitals-foot {
  display: flex;
  gap: 13px;
  margin-top: 7px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  color: rgba(233, 231, 223, 0.38);
}

.ammo-block {
  position: absolute;
  right: 33px;
  bottom: 39px;
  width: 285px;
  text-align: right;
}
.weapon-line {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 9px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  color: var(--dim);
  letter-spacing: 0.1em;
}
.weapon-line .mode { color: var(--orange); border: 1px solid rgba(255, 91, 33, 0.5); padding: 1px 5px; font-size: 8px; }
.ammo-line { display: flex; justify-content: flex-end; align-items: baseline; gap: 8px; margin-top: 2px; }
.ammo-mag {
  font-family: 'Share Tech Mono', monospace;
  font-size: 58px;
  line-height: 0.9;
  color: var(--ink);
  letter-spacing: -0.04em;
}
.ammo-mag.low { color: var(--red); animation: lowammo 0.9s ease-in-out infinite; }
@keyframes lowammo { 50% { opacity: 0.55; } }
.ammo-slash { color: var(--dim2); font-family: 'Share Tech Mono', monospace; font-size: 18px; }
.ammo-reserve { font-family: 'Share Tech Mono', monospace; font-size: 18px; color: var(--dim); }
.ammo-foot {
  display: flex;
  justify-content: flex-end;
  gap: 14px;
  margin-top: 5px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  color: var(--dim2);
}
.ammo-hint { color: rgba(255, 91, 33, 0.8); }
.weapon-slots { display: flex; justify-content: flex-end; gap: 4px; margin-top: 10px; }
.slot {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border: 1px solid rgba(233, 231, 223, 0.12);
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  color: var(--dim2);
}
.slot span { color: var(--dim); }
.slot.active { border-color: rgba(255, 91, 33, 0.55); color: var(--ink); background: rgba(255, 91, 33, 0.08); }
.slot.active span { color: var(--orange); }

.radio {
  position: absolute;
  left: 50%;
  bottom: 118px;
  transform: translateX(-50%) translateY(8px);
  width: min(610px, 55vw);
  padding: 9px 13px 10px;
  border-left: 2px solid var(--orange);
  background: linear-gradient(90deg, rgba(8, 10, 10, 0.82), rgba(8, 10, 10, 0.3) 80%, transparent);
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
}
.radio.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.radio-head {
  display: flex;
  align-items: center;
  gap: 5px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  color: var(--orange);
  letter-spacing: 0.18em;
}
.radio-dot { width: 4px; height: 4px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 6px var(--orange); }
.radio-freq { color: var(--dim2); margin-left: 4px; }
.radio-text { margin-top: 4px; font-size: 15px; line-height: 1.15; letter-spacing: 0.07em; color: rgba(233, 231, 223, 0.9); }

.killfeed {
  position: absolute;
  right: 33px;
  top: 44%;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: flex-end;
}
.kill-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 9px 4px 7px;
  background: rgba(8, 10, 10, 0.72);
  border-right: 2px solid var(--orange);
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.09em;
  animation: killIn 0.18s ease-out both;
}
.kill-item.head { border-right-color: var(--red); }
.kill-item.out { opacity: 0; transition: opacity 0.35s; }
.kill-x { color: var(--red); font-size: 12px; }
.kill-tag { color: var(--dim2); font-size: 7px; }
@keyframes killIn { from { transform: translateX(10px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44px;
  height: 44px;
  transform: translate(-50%, -50%);
  transition: opacity 0.12s;
}
#crosshair.hidden { opacity: 0; }
#crosshair .ch-line {
  position: absolute;
  background: rgba(239, 237, 225, 0.88);
  box-shadow: 0 0 2px rgba(0, 0, 0, 0.9);
}
#crosshair .ch-t { width: 1.5px; height: 7px; left: calc(50% - 0.75px); top: calc(50% - var(--cross-gap) - 7px); }
#crosshair .ch-b { width: 1.5px; height: 7px; left: calc(50% - 0.75px); top: calc(50% + var(--cross-gap)); }
#crosshair .ch-l { width: 7px; height: 1.5px; top: calc(50% - 0.75px); left: calc(50% - var(--cross-gap) - 7px); }
#crosshair .ch-r { width: 7px; height: 1.5px; top: calc(50% - 0.75px); left: calc(50% + var(--cross-gap)); }
#crosshair .ch-dot {
  position: absolute;
  left: calc(50% - 1px);
  top: calc(50% - 1px);
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background: var(--orange);
  box-shadow: 0 0 5px rgba(255, 91, 33, 0.9);
}
#crosshair.ads .ch-line { opacity: 0.16; }
#crosshair.ads .ch-dot { opacity: 0.25; }

#hitmarker {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 30px;
  height: 30px;
  transform: translate(-50%, -50%) rotate(45deg);
  opacity: 0;
  transition: opacity 0.07s;
}
#hitmarker.active { opacity: 1; }
#hitmarker i {
  position: absolute;
  width: 9px;
  height: 1.5px;
  background: rgba(255, 255, 245, 0.95);
  box-shadow: 0 0 5px rgba(255, 255, 240, 0.8);
}
#hitmarker i:nth-child(1) { left: 1px; top: 5px; transform: rotate(45deg); }
#hitmarker i:nth-child(2) { right: 1px; top: 5px; transform: rotate(-45deg); }
#hitmarker i:nth-child(3) { left: 1px; bottom: 5px; transform: rotate(-45deg); }
#hitmarker i:nth-child(4) { right: 1px; bottom: 5px; transform: rotate(45deg); }
#hitmarker.head i { background: #ffb25c; box-shadow: 0 0 7px rgba(255, 91, 33, 0.9); }

#damageDir {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 250px;
  height: 250px;
  transform: translate(-50%, -50%) rotate(0deg);
  border-radius: 50%;
  background: conic-gradient(from -18deg, transparent 0 26deg, rgba(255, 52, 41, 0.65) 31deg 45deg, transparent 50deg 360deg);
  mask: radial-gradient(circle, transparent 58%, #000 60%, #000 76%, transparent 78%);
  -webkit-mask: radial-gradient(circle, transparent 58%, #000 60%, #000 76%, transparent 78%);
  opacity: 0;
  transition: opacity 0.12s;
}
#damageDir.show { opacity: 1; }

.interact {
  position: absolute;
  left: 50%;
  bottom: 23%;
  transform: translateX(-50%) translateY(6px);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 13px 7px 8px;
  background: rgba(8, 10, 10, 0.78);
  border: 1px solid rgba(233, 231, 223, 0.16);
  font-size: 12px;
  letter-spacing: 0.09em;
  opacity: 0;
  transition: opacity 0.15s, transform 0.15s;
}
.interact.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.interact .key {
  display: grid;
  place-items: center;
  width: 23px;
  height: 23px;
  background: var(--orange);
  color: #0a0b0b;
  font-family: 'Share Tech Mono', monospace;
  font-size: 12px;
  font-weight: 700;
}

.lock-hint {
  position: absolute;
  left: 50%;
  bottom: 17%;
  transform: translateX(-50%);
  padding: 8px 15px;
  background: rgba(255, 91, 33, 0.9);
  color: #090a0a;
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.12em;
  pointer-events: auto;
  cursor: pointer;
  animation: hintPulse 2.2s ease-in-out infinite;
}
@keyframes hintPulse { 50% { opacity: 0.65; } }

.hud-foot {
  position: absolute;
  left: 33px;
  right: 33px;
  bottom: 14px;
  display: flex;
  justify-content: space-between;
  font-family: 'Share Tech Mono', monospace;
  font-size: 7.5px;
  letter-spacing: 0.08em;
  color: rgba(233, 231, 223, 0.28);
}
.hud-foot-mid { color: rgba(118, 255, 157, 0.35); }

/* ==========================================================================
