  background:
    linear-gradient(90deg, rgba(3, 4, 5, 0.94) 0%, rgba(3, 4, 5, 0.78) 30%, rgba(3, 4, 5, 0.15) 58%, rgba(3, 4, 5, 0.32) 100%),
    linear-gradient(0deg, rgba(3, 4, 5, 0.88) 0%, transparent 38%, transparent 78%, rgba(3, 4, 5, 0.55) 100%),
    radial-gradient(ellipse at 62% 40%, transparent 0%, rgba(0, 0, 0, 0.22) 70%);
}
.menu-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
