  animation: menuIn 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes menuIn { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: 'Share Tech Mono', monospace;
