}
.brand-tags { display: flex; gap: 7px; margin-top: 19px; }
.brand-tags span {
  padding: 4px 9px;
  border: 1px solid rgba(233, 231, 223, 0.16);
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
