  color: var(--dim);
}
.brand-tags span:last-child { border-color: rgba(255, 91, 33, 0.5); color: var(--orange); }

.briefing {
  position: absolute;
  right: 5.5vw;
  top: 21vh;
  width: 392px;
  background: linear-gradient(155deg, rgba(11, 13, 13, 0.93), rgba(7, 9, 9, 0.86));
  border: 1px solid rgba(233, 231, 223, 0.14);
  box-shadow: 0 25px 80px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(14px);
