  opacity: 0.8;
}
.briefing::before { left: -1px; top: -1px; border-width: 1px 0 0 1px; }
.briefing::after { right: -1px; bottom: -1px; border-width: 0 1px 1px 0; }
.briefing-top {
  display: flex;
  justify-content: space-between;
  padding: 13px 18px;
  border-bottom: 1px solid rgba(233, 231, 223, 0.12);
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.16em;
