  letter-spacing: 0.035em;
  color: rgba(233, 231, 223, 0.72);
}
.brief-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: rgba(233, 231, 223, 0.1);
  border: 1px solid rgba(233, 231, 223, 0.1);
}
.brief-grid div { background: #0b0d0d; padding: 8px 9px 9px; }
.brief-grid span { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7.5px; letter-spacing: 0.12em; color: var(--dim2); }
.brief-grid strong { display: block; margin-top: 3px; font-family: 'Share Tech Mono', monospace; font-size: 10px; color: var(--ink); font-weight: 400; letter-spacing: 0.04em; }
.brief-warning {
  margin-top: 13px;
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 8px;
  letter-spacing: 0.1em;
  color: rgba(255, 91, 33, 0.9);
}
.brief-warning span {
  display: grid;
  place-items: center;
  width: 13px;
  height: 13px;
  border: 1px solid rgba(255, 91, 33, 0.7);
  font-size: 8px;
}

.deploy-btn {
  position: relative;
  width: calc(100% - 40px);
  margin: 0 20px;
  height: 52px;
  border: 0;
  background: var(--orange);
  color: #0a0b0b;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 18px;
  cursor: pointer;
  font-family: 'Barlow Condensed', sans-serif;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.16em;
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  transition: background 0.16s, transform 0.16s;
}
.deploy-btn:hover { background: #ff7a43; transform: translateY(-1px); }
.deploy-btn:active { transform: translateY(1px); }
.btn-arrow { font-family: 'Share Tech Mono', monospace; font-size: 22px; }
.ghost-btn {
  width: calc(100% - 40px);
  margin: 9px 20px 0;
  height: 35px;
  border: 1px solid rgba(233, 231, 223, 0.17);
  background: transparent;
  color: var(--dim);
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.13em;
