  transition: border-color 0.16s, color 0.16s, background 0.16s;
}
.ghost-btn:hover { border-color: rgba(255, 91, 33, 0.6); color: var(--ink); background: rgba(255, 91, 33, 0.05); }
.ghost-btn.wide { width: calc(100% - 40px); margin: 20px 20px 0; }
.briefing-foot {
