}

/* ==========================================================================
   OVERLAYS
   ========================================================================== */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  background: rgba(3, 4, 5, 0.68);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: auto;
}
.overlay-card {
  width: min(590px, 90vw);
  background: linear-gradient(155deg, rgba(12, 14, 14, 0.97), rgba(6, 8, 8, 0.96));
  border: 1px solid rgba(233, 231, 223, 0.16);
  padding: 25px 28px 27px;
  position: relative;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65);
  animation: cardIn 0.22s ease-out both;
}
@keyframes cardIn { from { opacity: 0; transform: translateY(10px) scale(0.99); } to { opacity: 1; transform: none; } }
.overlay-card::before, .overlay-card::after {
  content: '';
  position: absolute;
  width: 28px;
  height: 28px;
  border-color: var(--orange);
  border-style: solid;
}
.overlay-card::before { left: -1px; top: -1px; border-width: 1px 0 0 1px; }
.overlay-card::after { right: -1px; bottom: -1px; border-width: 0 1px 1px 0; }
.overlay-head {
  display: flex;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(233, 231, 223, 0.14);
