  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: rgba(233, 231, 223, 0.12);
  border: 1px solid rgba(233, 231, 223, 0.12);
  margin: 24px 0 20px;
}
.pause-stats div { background: #0a0c0c; padding: 11px 12px 12px; }
.pause-stats span { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7.5px; letter-spacing: 0.1em; color: var(--dim2); }
.pause-stats strong { display: block; margin-top: 4px; font-family: 'Share Tech Mono', monospace; font-size: 15px; font-weight: 400; color: var(--ink); }
.pause-actions { display: flex; gap: 9px; margin-top: 9px; }
