.end-title {
  margin-top: 4px;
  font-size: 58px;
  line-height: 0.92;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--ink);
}
.end-title.win { color: var(--green); text-shadow: 0 0 35px rgba(118, 255, 157, 0.16); }
.end-sub { margin-top: 8px; font-family: 'Share Tech Mono', monospace; font-size: 10px; letter-spacing: 0.1em; color: var(--dim); }
.end-stats {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1px;
  background: rgba(233, 231, 223, 0.12);
  border: 1px solid rgba(233, 231, 223, 0.12);
  margin: 24px 0 20px;
}
.end-stat { background: #0a0c0c; padding: 10px 10px 11px; }
.end-stat span { display: block; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.08em; color: var(--dim2); }
.end-stat strong { display: block; margin-top: 4px; font-family: 'Share Tech Mono', monospace; font-size: 13px; font-weight: 400; color: var(--ink); }
.end-actions { display: flex; gap: 9px; }
.end-actions .deploy-btn { margin: 0; width: 52%; }
.end-actions .ghost-btn { margin: 0; width: 48%; }
.end-foot { margin-top: 20px; font-family: 'Share Tech Mono', monospace; font-size: 7px; letter-spacing: 0.12em; color: rgba(233, 231, 223, 0.26); }
.overlay.loss .end-title { color: var(--red); }

.controls-card { width: min(720px, 92vw); }
.controls-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: rgba(233, 231, 223, 0.1);
  border: 1px solid rgba(233, 231, 223, 0.1);
  margin-top: 20px;
}
.control-row {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #0a0c0c;
  padding: 8px 12px;
  font-family: 'Share Tech Mono', monospace;
  font-size: 9px;
  letter-spacing: 0.08em;
  color: var(--dim);
}
.control-row .key {
  display: inline-block;
  min-width: 67px;
  padding: 3px 6px;
  border: 1px solid rgba(233, 231, 223, 0.18);
  color: var(--ink);
  font-size: 8px;
  text-align: center;
}
.controls-note { margin-top: 15px; font-family: 'Share Tech Mono', monospace; font-size: 8px; line-height: 1.6; letter-spacing: 0.06em; color: var(--dim2); }

