  .menu-bottom { display: none; }
  .menu-case { display: none; }
  .obj-panel { width: 230px; }
  .radio { width: 70vw; bottom: 100px; }
  .killfeed { top: 38%; }
  .ammo-block { width: 220px; }
  .ammo-mag { font-size: 46px; }
  .vitals { width: 245px; }
  .compass-wrap { width: 280px; }
}

